// advances |fLineOfTokens| by |bytesToAdvance| bytes
void nsImapGenericParser::AdvanceTokenizerStartingPoint(
    int32_t bytesToAdvance) {
  NS_ASSERTION(bytesToAdvance >= 0, "bytesToAdvance must not be negative");
  if (!fStartOfLineOfTokens) {
    // The tokenizer needs to be re-initialized. bytesToAdvance was computed
    // against fCurrentLine, so it's only still valid if AdvanceToNextToken()
    // re-tokenizes that same line rather than fetching a new one.
    bool willAdvanceLine = !fCurrentLine || fAtEndOfLine;
    AdvanceToNextToken();
    if (!fStartOfLineOfTokens || willAdvanceLine) return;
  }
  // The last call to AdvanceToNextToken() cleared the token separator to '\0'
  // iff |fCurrentTokenPlaceHolder|.  We must recover this token separator now.
  if (fCurrentTokenPlaceHolder) {
    int endTokenOffset = fCurrentTokenPlaceHolder - fStartOfLineOfTokens - 1;
    if (endTokenOffset >= 0)
      fStartOfLineOfTokens[endTokenOffset] = fCurrentLine[endTokenOffset];
  }

  // Enforce the bound. A caller that derived
  // bytesToAdvance from a pointer that isn't in the tokenizer buffer would
  // otherwise leave fLineOfTokens, and with it fCurrentTokenPlaceHolder,
  // pointing at unrelated memory.
  int32_t consumed = int32_t(fLineOfTokens - fStartOfLineOfTokens);
  int32_t lineLength = fCurrentLine ? int32_t(strlen(fCurrentLine)) : 0;
  if (bytesToAdvance < 0 || consumed < 0 || consumed > lineLength ||
      bytesToAdvance > lineLength - consumed) {
    SetSyntaxError(true, "cannot advance beyond end of fLineOfTokens");
    return;
  }
  fLineOfTokens += bytesToAdvance;
  fCurrentTokenPlaceHolder = fLineOfTokens;
}
